  // ---- virtual canvas ----
  var BW = 520, BH = 680;
  var TWO_PI = Math.PI * 2;
  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
  function byId(id) { for (var i=0;i<CATALOG.length;i++) if (CATALOG[i].id===id) return CATALOG[i]; return null; }
  function ordinal(n){ return n===1?"1st":n===2?"2nd":n===3?"3rd":n+"th"; }

  function curveAt(dist, spec) {
    if (!spec || !spec.waves) return 0;
    var v = 0;
    for (var i=0;i<spec.waves.length;i++){ var w=spec.waves[i]; v += Math.sin(dist*w.f + (w.p||0)) * w.a; }
    return v * spec.amp;
  }
  function buildTrackPath(length, spec) {
    var N = 240, stepD = length / N, raw = [];
    var x = 0, y = 0, heading = -Math.PI/2;
    for (var i=0;i<=N;i++){
      var d = i*stepD;
      heading += curveAt(d, spec) * 0.006 * stepD;
      x += Math.cos(heading)*stepD; y += Math.sin(heading)*stepD;
      raw.push({x:x,y:y});
    }
    var minX=Infinity,maxX=-Infinity,minY=Infinity,maxY=-Infinity;
    for (i=0;i<raw.length;i++){ var p=raw[i]; if(p.x<minX)minX=p.x; if(p.x>maxX)maxX=p.x; if(p.y<minY)minY=p.y; if(p.y>maxY)maxY=p.y; }
    var w=(maxX-minX)||1, h=(maxY-minY)||1;
    var scale=1/Math.max(w,h), pad=0.08, mx=Math.max(w,h);
    var pts = raw.map(function(p){
      return {
        nx: pad + (1-2*pad)*((p.x-minX)*scale + (mx-w)*scale/2),
        ny: pad + (1-2*pad)*((p.y-minY)*scale + (mx-h)*scale/2)
      };
    });
    return { pts: pts, N: N };
  }

  function deriveStats(equipped) {
    var base = { speed: 150, accel: 90, handling: 2.0 };
    for (var i=0;i<SLOTS.length;i++){
      var item = byId(equipped[SLOTS[i]]);
      if (item && item.stats){
        base.speed += item.stats.speed||0;
        base.accel += item.stats.accel||0;
        base.handling += item.stats.handling||0;
      }
    }
    return base;
  }

  // ---- shared boat sprite ----
  function drawBoatSprite(ctx, x, y, s, equipped, lean) {
    lean = lean || 0;
    var hull = byId(equipped.hull) || byId("hull_oak");
    var sail = byId(equipped.sail) || byId("sail_plain");
    var fig = byId(equipped.figure);
    ctx.save(); ctx.translate(x, y); ctx.rotate(lean);
    ctx.fillStyle = hull.color;
    ctx.beginPath();
    ctx.moveTo(0,-22*s); ctx.lineTo(11*s,8*s); ctx.lineTo(7*s,20*s);
    ctx.lineTo(-7*s,20*s); ctx.lineTo(-11*s,8*s); ctx.closePath(); ctx.fill();
    ctx.fillStyle = PAL.hullDark; ctx.fillRect(-11*s,8*s,22*s,4*s);
    ctx.fillStyle = "rgba(0,0,0,0.18)"; ctx.fillRect(-3*s,-10*s,6*s,28*s);
    if (fig && fig.id==="fig_lamb"){ ctx.fillStyle="#e8e0cf"; ctx.beginPath(); ctx.arc(0,-24*s,3.2*s,0,TWO_PI); ctx.fill(); }
    if (fig && fig.id==="fig_lion"){ ctx.fillStyle=PAL.gold; ctx.beginPath(); ctx.arc(0,-24*s,3.6*s,0,TWO_PI); ctx.fill(); ctx.fillStyle=PAL.goldDark; ctx.fillRect(-3.6*s,-26*s,7.2*s,2*s); }
    ctx.fillStyle = PAL.hullDark; ctx.fillRect(-1.2*s,-6*s,2.4*s,14*s);
    ctx.fillStyle = sail.color;
    ctx.beginPath(); ctx.moveTo(0,-16*s); ctx.lineTo(12*s,4*s); ctx.lineTo(-12*s,4*s); ctx.closePath(); ctx.fill();
    ctx.strokeStyle = "rgba(0,0,0,0.15)"; ctx.stroke();
    if (sail.mark==="cross"){ ctx.fillStyle=PAL.blood; ctx.fillRect(-1*s,-12*s,2*s,12*s); ctx.fillRect(-4*s,-8*s,8*s,2*s); }
    if (sail.mark==="bolt"){ ctx.strokeStyle=PAL.gold; ctx.lineWidth=1.6*s; ctx.beginPath(); ctx.moveTo(2*s,-12*s); ctx.lineTo(-2*s,-4*s); ctx.lineTo(2*s,-4*s); ctx.lineTo(-2*s,2*s); ctx.stroke(); }
    if (equipped.engine==="eng_double"){ ctx.fillStyle=sail.color; ctx.globalAlpha=0.85; ctx.beginPath(); ctx.moveTo(0,-4*s); ctx.lineTo(8*s,12*s); ctx.lineTo(-8*s,12*s); ctx.closePath(); ctx.fill(); ctx.globalAlpha=1; }
    // ── THE KNIGHT AT THE TILLER ── the boat was beautifully customisable and
    //   completely empty: hull, sail, mark and figurehead all yours, and nobody
    //   sailing it. He sits aft, in the same blue and steel he wears everywhere.
    //   Drawn LAST so he reads in front of the sail, and small enough not to
    //   crowd the parts you paid for.
    var q=function(lx,ly,w,h,c){ ctx.fillStyle=c; ctx.fillRect(lx*s,ly*s,w*s,h*s); };
    q(-3,10,6,6,'#3b6fd4'); q(-3,10,2,6,'#5a8ae8');       // tunic
    q(-3,15,6,1,'#c9a94a');                                // belt
    q(-4,12,1,3,'#c9cdd6'); q(3,12,1,3,'#c9cdd6');         // arms on the tiller
    q(-2,6,4,4,'#c9cdd6'); q(-2,6,4,1,'#eef0f4');          // helm
    q(-3,6,1,4,'#141c2e'); q(2,6,1,4,'#141c2e');
    q(-2,8,2,1,'#1a2740');                                 // visor
    q(-1,5,3,1,'#e8452f');                                 // plume
    ctx.restore();
  }
  function drawRivalBoat(ctx, x, y, s, color) {
    ctx.save(); ctx.translate(x, y);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.moveTo(0,-16*s); ctx.lineTo(9*s,10*s); ctx.lineTo(-9*s,10*s); ctx.closePath(); ctx.fill();
    ctx.fillStyle = PAL.sailShade;
    ctx.beginPath(); ctx.moveTo(0,-14*s); ctx.lineTo(8*s,0); ctx.lineTo(-8*s,0); ctx.closePath(); ctx.fill();
    ctx.restore();
  }

